<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Accessor\TenantConfigAllowRegisterAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigAllowRegisterAccessor trait.
 *
 * Covers null default, string/VO assignment via withAllowRegister,
 * getAllowRegister/allowRegister accessors, and isAllowRegisterChanged with/without original.
 */
class TenantConfigAllowRegisterAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withAllowRegister creates a new instance with the AllowRegister set
     * from a string value, and getAllowRegister returns the primitive string.
     */
    public function testWithAllowRegisterFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigAllowRegisterAccessorUnitTest();

        // Act
        $result = $holder->withAllowRegister(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isAllowRegister());
    }
    /**
     * Asserts that withallowRegister has access to the value object
     * from a string value, and getAllowRegister returns the primitive string.
     */
    public function testWithAllowRegisterFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigAllowRegisterAccessorUnitTest();

        // Act
        $result = $holder->withAllowRegister(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->allowRegister()->value());
    }
    public function testChangedAllowRegister(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigAllowRegisterAccessorUnitTest();
        $original = $holder->withAllowRegister(true);
        $same = $holder->withAllowRegister(true);
        $modified = $holder->withAllowRegister(false);

        // Act
        $unchanged = $holder->isAllowRegisterChanged();
        $withSame = $original->isAllowRegisterChanged($same);
        $withDiferent = $original->isAllowRegisterChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantConfigAllowRegisterAccessorUnitTest
{
    use TenantConfigAllowRegisterAccessor;
}
